description:
A local tool exposes a small HTTP API on `127.0.0.1:PORT`. Write the checks from lesson 5.05 that every request must pass before it is handled:

```cpp
struct Request
{
    std::string method;                                  // "GET", "POST", ...
    std::map<std::string, std::string> headers;          // header names in lower case
};

bool constantTimeEquals(const std::string& a, const std::string& b);
std::string checkRequest(const Request& r, std::uint16_t port, const std::string& token);
```

- **constantTimeEquals**: false if the lengths differ; otherwise it compares **every** byte, combining the differences, and only decides at the end (no early return on the first mismatch).
- **checkRequest** returns `"ok"` or the reason for refusing, checking in this order:
  1. `host` must be exactly `localhost:PORT` or `127.0.0.1:PORT`: else `"bad host"` (the DNS rebinding defence).
  2. For any method other than `GET`, an `origin` header, if present, must be `http://localhost:PORT` or `http://127.0.0.1:PORT`: else `"bad origin"`.
  3. `authorization` must be `Bearer ` followed by the token, compared in constant time: else `"bad token"`.

starter.solution.cpp:
#include <cstdint>
#include <map>
#include <string>

struct Request
{
    std::string method;
    std::map<std::string, std::string> headers;
};

bool constantTimeEquals(const std::string& a, const std::string& b) { return a == b; }
std::string checkRequest(const Request& r, std::uint16_t port, const std::string& token) { return "ok"; }

solution.solution.cpp:
#include <cstdint>
#include <map>
#include <string>

struct Request
{
    std::string method;
    std::map<std::string, std::string> headers;
};

bool constantTimeEquals(const std::string& a, const std::string& b)
{
    if (a.size() != b.size()) return false;
    unsigned char diff{ 0 };
    for (std::size_t i{ 0 }; i < a.size(); ++i) diff |= static_cast<unsigned char>(a[i] ^ b[i]);
    return diff == 0;
}

std::string checkRequest(const Request& r, std::uint16_t port, const std::string& token)
{
    const std::string p{ std::to_string(port) };
    const auto header = [&](const char* name) -> const std::string* {
        const auto it{ r.headers.find(name) };
        return it == r.headers.end() ? nullptr : &it->second;
    };
    const std::string* host{ header("host") };
    if (!host || (*host != "localhost:" + p && *host != "127.0.0.1:" + p)) return "bad host";
    if (r.method != "GET")
        if (const std::string* origin{ header("origin") })
            if (*origin != "http://localhost:" + p && *origin != "http://127.0.0.1:" + p) return "bad origin";
    const std::string* auth{ header("authorization") };
    if (!auth || auth->rfind("Bearer ", 0) != 0 || !constantTimeEquals(auth->substr(7), token)) return "bad token";
    return "ok";
}

unitTests:
static const std::string TOKEN{ "0f3a9c2e7b1d4a6f8e2c0b9d7a5f3e1c" };
static Request good() { return { "POST", { { "host", "127.0.0.1:50123" }, { "authorization", "Bearer " + TOKEN } } }; }

TEST("constant-time comparison") {
    CHECK(constantTimeEquals("abc", "abc"));
    CHECK(!constantTimeEquals("abc", "abd"));
    CHECK(!constantTimeEquals("abc", "ab"));
    CHECK(constantTimeEquals("", ""));
}
TEST("a good request") {
    CHECK_EQ(checkRequest(good(), 50123, TOKEN), std::string("ok"));
    Request local{ good() };
    local.headers["host"] = "localhost:50123";
    local.headers["origin"] = "http://localhost:50123";
    CHECK_EQ(checkRequest(local, 50123, TOKEN), std::string("ok"));
}
TEST("DNS rebinding is refused by the host check") {
    Request r{ good() };
    r.headers["host"] = "attacker.example:50123";
    CHECK_EQ(checkRequest(r, 50123, TOKEN), std::string("bad host"));
    r.headers["host"] = "127.0.0.1:50124";
    CHECK_EQ(checkRequest(r, 50123, TOKEN), std::string("bad host"));
    r.headers.erase("host");
    CHECK_EQ(checkRequest(r, 50123, TOKEN), std::string("bad host"));
}
TEST("origins and tokens") {
    Request r{ good() };
    r.headers["origin"] = "https://evil.example";
    CHECK_EQ(checkRequest(r, 50123, TOKEN), std::string("bad origin"));
    r.method = "GET";
    CHECK_EQ(checkRequest(r, 50123, TOKEN), std::string("ok"));
    Request t{ good() };
    t.headers["authorization"] = "Bearer " + std::string(32, '0');
    CHECK_EQ(checkRequest(t, 50123, TOKEN), std::string("bad token"));
    t.headers["authorization"] = TOKEN;
    CHECK_EQ(checkRequest(t, 50123, TOKEN), std::string("bad token"));
    t.headers.erase("authorization");
    CHECK_EQ(checkRequest(t, 50123, TOKEN), std::string("bad token"));
}

